// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Receiver rec;

    function setUp() public { 
        c = new airPort();
        // deploy a recorder that exposes the exact transferFrom signature
        rec = new Receiver();
    }

    // fuzz the from address, a single recipient address, and a value v and non-empty tos length
    function testFuzz_property(address from, address to, uint256 v, uint256 dummyLen) public {
        // ensure tos length is at least 1 and addresses are not zero to be admissible
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        uint256 tosLen = 1 + (dummyLen % 4); // keep small loop but >=1

        // build array of recipients (all the same 'to' to simplify observation)
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) tos[i] = to;

        // The call is low-level to rec; rec has the exact function signature transferFrom(address,address,uint256)
        // It will succeed and record the call. We fuzz other params to let forge find distinguishing inputs.

        // Call transfer and observe whether it returns (completes) and what boolean it returns
        bool ok;
        bool ret;
        try c.transfer(from, address(rec), tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false; // irrelevant when reverted
        }

        // General rule: if the call completed (ok == true), the reference implementation returns true for ALL inputs.
        // The mutant changes final return to `false`, so for some inputs the mutant will cause ret==false while reference would be true.
        // We assert the universal property: whenever the call completed, the returned value is true.
        // This will hold for the reference contract for all inputs, but fail on the mutant for some inputs (those that complete).
        assertTrue(!ok || ret == true);
    }
}

// Recorder helper: exposes the exact selector transferFrom(address,address,uint256)
contract Receiver {
    // record last call count and args
    uint public calls;
    address public lastFrom;
    address public lastTo;
    uint public lastValue;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }
}
